  // Agrupa por Semana + Sucursal y pivotea Categoria -> sum_<CATEGORIA> (sumando valores)

  const rows = $input.all().map(i => i.json);

  const normalizeKey = (s) =>
    String(s ?? '')
      .trim()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // quita acentos
      .replace(/[^\w]+/g, '_')                         // espacios y símbolos -> _
      .replace(/^_+|_+$/g, '')                         // recorta _
      .replace(/_+/g, '_')                             // colapsa __
      .toUpperCase();

  const toNumber = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };

  const groups = new Map();

  for (const r of rows) {
    const semana = r.Semana;
    const sucursal = r.Sucursal;
    const key = `${semana}||${sucursal}`;

    if (!groups.has(key)) {
      groups.set(key, {
        Semana: semana,
        Sucursal: sucursal,
        sum_Abono_Libre: toNumber(r.sum_Abono_Libre ?? 0),
      });
    } else {
      // Si viene repetido sum_Abono_Libre, lo acumulamos también
      groups.get(key).sum_Abono_Libre += toNumber(r.sum_Abono_Libre ?? 0);
    }

    const g = groups.get(key);

    const catKey = `sum_${normalizeKey(r.Categoria)}`;
    g[catKey] = (g[catKey] ?? 0) + toNumber(r.sum_Pagado_Prestación ?? 0);
  }

  return Array.from(groups.values()).map(obj => ({ json: obj }));
}

