const TZ = 'America/Montevideo';
const pad = n => String(n).padStart(2, '0');

// Fecha inicio fija
const inicio = new Date(Date.UTC(2026, 2, 10)); // 10 mar, medianoche UTC

// Hoy en Montevideo con en-CA → formato YYYY-MM-DD confiable
const hoyStrMVD = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
const [y, m, d] = hoyStrMVD.split('-').map(Number);
const ayer = new Date(Date.UTC(y, m - 1, d - 1)); // ayer, medianoche UTC

const items = [];
const cursor = new Date(inicio);

while (cursor <= ayer) {
  const diaSemana = cursor.getUTCDay(); // 0 = domingo

  if (diaSemana !== 0) {
    const yyyy = cursor.getUTCFullYear();
    const mm = pad(cursor.getUTCMonth() + 1);
    const dd = pad(cursor.getUTCDate());
    const fecha = `${yyyy}-${mm}-${dd}`;

    const url = "https://api.dentalink.healthatom.com/api/v1/pagos?q="
      + encodeURIComponent('{"fecha_recepcion":{"eq":"' + fecha + '"}}');

    // Usar mediodía UTC para el display evita cualquier ambigüedad de timezone
    const fechaDisplayRaw = new Date(fecha + 'T12:00:00Z').toLocaleDateString('es-UY', {
      timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long'
    });
    const fechaDisplay = fechaDisplayRaw.charAt(0).toUpperCase() + fechaDisplayRaw.slice(1);

    items.push({ json: { fecha, url, fechaDisplay } });
  }

  cursor.setUTCDate(cursor.getUTCDate() + 1);
}

return items;

const items = $input.all().map(i => i.json);

// ← CAMBIO: fecha viene del item actual del loop, no de new Date()
const { fechaDisplay } = $('Loop Over Items1').first().json;

const ORDEN_SUCURSALES = [
  'SUY 1 Centro',
  'SUY 2 Paso Molino',
  'SUY 3 Las Piedras',
  'SUY 4 Lagomar - Clínica del Lago'
];

const porSucursal = {};
for (const row of items) {
  const suc = row.nombre_sucursal;
  if (!porSucursal[suc]) porSucursal[suc] = [];
  porSucursal[suc].push({ medio: row.medio_pago, monto: row.sum_monto_pago });
}

const sucursalesOrdenadas = Object.keys(porSucursal).sort((a, b) => {
  const ia = ORDEN_SUCURSALES.findIndex(s => a.toLowerCase().includes(s.toLowerCase().split(' ').slice(0,3).join(' ')));
  const ib = ORDEN_SUCURSALES.findIndex(s => b.toLowerCase().includes(s.toLowerCase().split(' ').slice(0,3).join(' ')));
  return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
});

const fmt = n => '$' + Number(n).toLocaleString('es-UY', { minimumFractionDigits: 0 });

const secciones = sucursalesOrdenadas.map(sucursal => {
  const pagos = porSucursal[sucursal];
  const total = pagos.reduce((acc, p) => acc + p.monto, 0);
  const filas = pagos
    .sort((a, b) => b.monto - a.monto)
    .map(p => `
      <tr>
        <td style="padding:5px 0;color:#555;font-size:14px;">${p.medio}</td>
        <td style="padding:5px 0;text-align:right;color:#333;font-size:14px;">${fmt(p.monto)}</td>
